 const capture=()=>{const fields=Object.fromEntries(new FormData($('#service-form')));Object.assign(s,fields);s.self_sni=fields.self_sni==='true';s.sniffing=fields.sniffing==='true';s.allow_insecure=fields.allow_insecure==='true';};
 if(proxy)$('[name="transport"]').onchange=e=>{const next=e.target.value;capture();s.transport=next;s.transport_settings={};s.client_transport_settings={};if(next!=='tcp')s.flow='';protocolFields(id,s);};
 const security=$('[name="security"]');
