function shareSection(id,title){return `<section class="share-section"><strong>${title}</strong><div class="share-actions"><button type="button" class="secondary" id="${id}-copy">Копировать</button><button type="button" class="secondary" id="${id}-qr" aria-expanded="false">Показать QR</button><button type="button" class="secondary" id="${id}-download">Скачать файл</button><button type="button" class="secondary" id="${id}-show" aria-expanded="false">Показать текст</button></div><div class="share-qr" id="${id}-qr-code" hidden></div><pre class="code" id="${id}-text" hidden></pre></section>`;}
function bindShare(id,value,filename){const show=$('#'+id+'-show'),text=$('#'+id+'-text'),qrButton=$('#'+id+'-qr'),qrBox=$('#'+id+'-qr-code');show.onclick=()=>{const visible=text.hidden;text.hidden=!visible;text.textContent=visible?value:'';show.textContent=visible?'Скрыть текст':'Показать текст';show.setAttribute('aria-expanded',String(visible));};$('#'+id+'-copy').onclick=async()=>{try{await navigator.clipboard.writeText(value);toast('Скопировано');}catch{toast('Не удалось скопировать. Нажмите «Показать текст» и скопируйте вручную.',true);}};$('#'+id+'-download').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([value],{type:'text/plain;charset=utf-8'}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};qrButton.onclick=()=>{if(!qrBox.hidden){qrBox.hidden=true;qrBox.replaceChildren();qrButton.textContent='Показать QR';qrButton.setAttribute('aria-expanded','false');return;}if(new TextEncoder().encode(value).length>2953){toast('Конфигурация слишком большая для QR-кода. Скачайте файл.',true);return;}try{qrcode.stringToBytes=qrcode.stringToBytesFuncs['UTF-8'];const qr=qrcode(0,'L');qr.addData(value);qr.make();qrBox.innerHTML=qr.createSvgTag({cellSize:4,scalable:true,alt:'QR-код'});qrBox.hidden=false;qrButton.textContent='Скрыть QR';qrButton.setAttribute('aria-expanded','true');}catch(e){toast('Не удалось создать QR-код. Скачайте файл или скопируйте текст.',true);}};}
async function showProfile(id,full=false){const u=state.users.find(u=>u.id===id);const result=await api('users/'+id+(full?'/config':'/profile'));const service=state.services.find(s=>s.id===u.service_id);if(service?.protocol==='webproxy'){openModal('Telegram · '+u.name,'Добавьте прокси в Telegram по ссылке. Это подключение не входит в подписку.',shareSection('profile-share','Ссылка для добавления в Telegram'),`<a class="primary" href="${esc(result.content)}">Добавить в Telegram ↗</a>`);bindShare('profile-share',result.content,'telegram-proxy-'+u.id+'.txt');return;}const owner=(state.people||[]).find(p=>p.id===u.person_id);const url=owner?location.origin+'/subscription/'+owner.token:state.services.find(s=>s.id===u.service_id)?.protocol==='wdtt'?location.origin+'/turn-sub/'+u.token:new URL('sub/'+u.token,document.baseURI).href;openModal('Подключение · '+u.name,'Импортируйте ссылку или файл в YPtun. Передавайте их только владельцу доступа.',shareSection('profile-share','Профиль подключения')+shareSection('subscription-share','Ссылка на подписку'),`<button class="secondary" data-action="${owner?'person-rotate':'rotate'}" data-id="${owner?owner.id:id}">Сменить ссылку</button>${['vless','vmess','trojan'].includes(state.services.find(s=>s.id===u.service_id)?.protocol)?`<button class="secondary" data-action="full-profile" data-id="${id}">Полный JSON</button>`:''}`);bindShare('profile-share',result.content,'yptun-'+u.id+(result.content.trim().startsWith('{')?'.json':'.txt'));bindShare('subscription-share',url,'yptun-subscription.txt');}
function confirmAction(title,description,action,id){openModal(title,description,`<p style="font-size:12px;line-height:1.8">${esc(description)}</p>`,`<button class="secondary" data-action="close">Отмена</button><button class="danger" data-action="${action}" data-id="${id}" data-confirmed="1">Подтвердить</button>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-page]');if(!b||busy)return;if(b.dataset.page){navigate(b.dataset.page);return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;try{if(action.startsWith('person-')||action==='edit-access'||action==='turn-limit'){await peopleAction(action,id);return;}if(action==='close'){modal.close();return;}if(action==='turn-edit-user'){const u=await api('users/'+id+'/settings');await turnUserForm(u.service_id,u);return;}if(action==='turn-hashes'){turnHashes();return;}if(action==='random-port'){const result=await api('service-defaults',{protocol:$('[name="protocol"]').value,exclude_port:$('[name="port"]').value});$('[name="port"]').value=result.port;toast('Выбран свободный случайный порт: '+result.port);return;}if(action==='generate-cert'){await generateServiceCertificate(b);return;}if(action==='image-op'){await imageOperation(id,b.dataset.operation);return;}if(action==='create'){createForm(b.dataset.protocol||'vless');return;}if(action==='add-user'){userForm(id);return;}if(action==='full-profile'){await showProfile(id,true);return;}if(action==='profile'){await showProfile(id);return;}if(action==='details'){const s=state.services.find(x=>x.id===id);openModal(s.name,'Управление службой',`<div class="tip"><strong>${esc(s.protocol.toUpperCase())} · ${esc(s.host)}:${s.port}</strong>Служба выполняется на хосте панели. Поле адреса используется в клиентских профилях.</div><p class="mono">Состояние: ${s.running?'контейнер работает':'контейнер остановлен или недоступен'}</p><div class="actions" style="flex-wrap:wrap"><button data-action="edit" data-id="${id}">Редактировать конфиг</button><button data-action="restart" data-id="${id}">Перезапустить</button><button data-action="logs" data-id="${id}">Журнал Docker</button><a class="secondary" href="api/services/${id}/export" download>Скачать пакет ZIP ↗</a><button data-action="delete" data-id="${id}" style="color:#a34e41">Удалить службу</button></div>`);return;}if(action==='edit'){createForm(null,await api('services/'+id+'/settings'));return;}if(action==='logs'){const r=await api('services/'+id+'/logs');openModal('Журнал службы','Последние 100 строк Docker',`<pre class="code">${esc(r.content)}</pre>`);return;}if(['delete','delete-user','toggle','rotate','stop'].includes(action)&&!b.dataset.confirmed){const msg={delete:'Служба и её пользователи будут удалены. Сначала остановите контейнер.', 'delete-user':'Генератор: ключ будет отозван, служба перезапустится. Свой движок: сначала остановите службу и вручную удалите ключ из её конфига.',toggle:'Доступ изменится. Работающая служба перезапустится; возможен краткий разрыв соединений.',rotate:'Старая ссылка подписки перестанет работать. Сам VPN-ключ не изменится.',stop:'VPN-подключения этой службы будут разорваны.'};confirmAction('Подтвердите действие',msg[action],action,id);return;}busy=true;b.disabled=true;const kind=['toggle','delete-user','rotate'].includes(action)?'users':'services';await api(`${kind}/${id}/${action==='delete-user'?'delete':action}`,{});modal.close();await load();toast('Изменения применены');}catch(err){toast(err.message,true);}finally{busy=false;b.disabled=false;}});
