async function generateServiceCertificate(button){
 busy=true;button.disabled=true;
 try{
  $('#certificate-status').textContent='Выпускается сертификат…';
  const result=await api('certificates',{mode:$('[name="certificate_mode"]').value,host:$('[name="certificate_host"]').value});
  $('[name="certificate"]').value=result.certificate;$('[name="private_key"]').value=result.private_key;$('[name="certificate_id"]').value=result.certificate_id;$('[name="sni"]').value=result.host;
  $('#certificate-status').textContent='Сертификат готов · '+result.expires+(result.mode==='domain'?' · автопродление':' · самоподписанный; настройте доверие на клиенте');
  toast('Сертификат выпущен. Сохраните службу.');
 }catch(e){$('#certificate-status').textContent=e.message;toast(e.message,true);}finally{busy=false;button.disabled=false;}
}
let imageTimer;
function updateImageNotice(){
 const updates=state.image_updates||{},count=updates.count||0,badge=$('#image-update-count'),notice=$('#image-update-notice');
 if(badge){badge.hidden=!count;badge.textContent=count;}
 if(notice){notice.hidden=!count;notice.textContent=`Обновления образов: ${count} ↗`;}
}
async function refreshImageUpdates(){
 if($('#shell').hidden)return;
 try{state.image_updates=await api('image-updates');updateImageNotice();}catch{}
}
function imageUpdateText(u){
 if(!u?.checked_at)return 'Обновления ещё не проверялись';
 const when=new Date(u.checked_at*1000).toLocaleString('ru');
 if(u.error)return `Не удалось проверить: ${esc(u.error)} · ${when}${u.available?' · ранее было найдено обновление':''}`;
 return `${u.available?'Доступно обновление':u.installed?'Установлена актуальная версия':'Образ ещё не установлен'} · ${when}`;
}
async function loadImages(){
 try{
  const items=await api('images');if(page!=='images')return;
  await refreshImageUpdates();if(page!=='images')return;
  const checking=state.image_updates?.checking;
  $('#image-list').innerHTML=`<div class="section-heading"><span class="mono">${checking?'Проверка обновлений выполняется…':'Проверка при открытии вкладки'}</span><button class="secondary" data-action="image-op" data-id="all" data-operation="check-updates" ${checking?'disabled':''}>Проверить все обновления</button></div><div class="notice">Обновление скачивает или собирает образ. Чтобы применить его к работающей службе, перезапустите её в разделе «Службы». Службы со своим Docker-образом сохраняют выбранный образ.</div><div class="catalog">${items.map(i=>`<article class="protocol-card"><span class="badge ${i.update?.available?'amber':i.local?'green':''}">${i.update?.available?'Доступно обновление':i.local?'Образ установлен':'Не установлен'}</span><h2>${esc(i.name)}</h2><div class="mono" style="overflow-wrap:anywhere">${esc(i.reference)}</div><p>${esc(i.note||'Готовый образ разработчика проекта.')}</p><p class="mono">${imageUpdateText(i.update)}</p>${i.update?.available?`<p class="mono">Новая версия: ${esc(i.update.revision?.slice(0,12)||i.update.reference)}${i.update.digest?' · '+esc(i.update.digest.slice(0,19)):''}</p>`:''}<a class="text-btn" target="_blank" rel="noreferrer" href="${esc(i.source)}">Исходники ↗</a>${i.revision?`<p class="mono">Выбранная ревизия: ${esc(i.revision.slice(0,12))}</p>`:''}<div class="actions" style="margin-top:15px"><button data-action="image-op" data-id="${i.id}" data-operation="check-updates" ${i.job?.status==='running'?'disabled':''}>Проверить обновления</button>${i.update?.available?`<button class="primary" data-action="image-op" data-id="${i.id}" data-operation="update" ${i.job?.status==='running'||i.update.error?'disabled':''}>Обновить</button>`:''}<button data-action="image-op" data-id="${i.id}" data-operation="${i.kind==='build'?'build':'pull'}" ${i.job?.status==='running'?'disabled':''}>${i.kind==='build'?'Пересобрать':'Скачать'}</button></div>${i.job?`<p class="mono">${esc(i.job.action)} · ${esc(i.job.status)} ${esc(i.job.error||'')}</p>${i.job.log?`<details><summary>Журнал операции</summary><pre class="code">${esc(i.job.log)}</pre></details>`:''}`:''}</article>`).join('')}</div>`;
  clearTimeout(imageTimer);if(checking||items.some(i=>i.job?.status==='running'))imageTimer=setTimeout(loadImages,4000);
 }catch(e){if(page==='images')$('#image-list').textContent=e.message;}
}
