async function turnHashes(){const r=await api('turn-hashes');openModal('Библиотека VK-хешей','Хеши звонков VK для назначения подписчикам.',`<form id="turn-hash-form"><label>Добавить хеши (до 4 за раз)<textarea name="hashes" required></textarea></label><pre class="code">${esc(r.hashes.join('\n')||'Библиотека пуста')}</pre><p id="form-error" class="form-error"></p></form>`,`<button class="secondary" data-action="close">Закрыть</button><button class="primary" type="submit" form="turn-hash-form">Добавить</button>`);}

let currentServiceDefaults=null;
function advancedGroup(root,title='Дополнительно'){
 let d=root.querySelector(':scope > details.minimal-advanced');
 if(!d){d=document.createElement('details');d.className='minimal-advanced full';d.innerHTML=`<summary>${esc(title)}</summary><div class="grid advanced-fields"></div>`;root.append(d);}
 return d.querySelector('.advanced-fields');
}
function moveFields(root,names,target){for(const name of names){const input=root.querySelector(`[name="${name}"]`);const label=input?.closest('label');if(label&&!target.contains(label))target.append(label);}}
async function createForm(protocol='vless',existing=null){
 try{currentServiceDefaults=existing?null:await api('service-defaults',{protocol});renderServiceForm(protocol,existing);const f=$('#service-form'),extra=advancedGroup(f.querySelector('.grid'),'Адрес сервера и порт');moveFields(f,['port'],extra);extra.insertAdjacentHTML('beforeend',field('image_override','Docker-образ (пусто — стандартный)',existing?.image_override||'','placeholder="registry/image:tag"'));extra.insertAdjacentHTML('beforeend','<button class="secondary" type="button" data-action="random-port">Другой случайный порт</button>');if((existing?.protocol||protocol)!=='webproxy'&&$('[name="host"]').value!=='127.0.0.1')moveFields(f,['host'],extra);$('[name="name"]').required=false;}
 catch(e){toast(e.message,true);}
}
function protocolFields(id,s){
 if(id==='webproxy'){const form=$('#service-form'),host=form.querySelector('[name="host"]');if(host)form.querySelector('.grid').insertBefore(host.closest('label'),form.querySelector('#protocol-fields'));}
 const reroll=document.querySelector('[data-action="random-port"]');if(reroll)reroll.hidden=false;
 if(state.protocols.find(p=>p.id===id)?.mode==='custom'){minimalCustomFields(id,s);return;}
 advancedProtocolFields(id,s);
 if(id==='wdtt'){const r=$('#protocol-fields');moveFields(r,['wg_port','local_port','dns'],advancedGroup(r));return;}
 simplifyNative(id);
}
function simplifyNative(id){
 if(id==='webproxy')return;
 const root=$('#protocol-fields');if(!root)return;
 if(root.querySelector('[name="certificate"]')&&!root.querySelector('.panel-cert-notice'))root.insertAdjacentHTML('afterbegin','<div class="notice panel-cert-notice">По умолчанию используется сертификат панели. Для другого сертификата заполните поля или выпустите его вручную.</div>');
 const extra=advancedGroup(root);
 moveFields(root,['listen','sniffing','path','transport_host','fingerprint','alpn','tls_min','allow_insecure','flow','obfs','kcp_seed','method'],extra);
 for(const title of root.querySelectorAll('.group-title'))title.hidden=true;
 for(const name of ['certificate','private_key']){const input=root.querySelector(`[name="${name}"]`);if(input)input.required=false;}
 moveFields(root,['certificate','private_key'],extra);
 const own=root.querySelector('[name="self_sni"]')?.value==='true';
 const sni=root.querySelector('[name="sni"]')?.closest('label');
 if(sni){if(own||root.querySelector('[name="security"]')?.value==='tls')extra.append(sni);else root.querySelector('.grid')?.append(sni);}
 const transport=root.querySelector('[name="transport"]')?.value;
 if(['ws','httpupgrade','grpc','xhttp'].includes(transport)){
  const input=root.querySelector('[name="path"]');if(input?.value==='/tunnel')input.closest('label').querySelector('small')?.remove();
 }
 // XDrive credentials and storage location are essential, so its JSON stays visible.
 const json=root.querySelector('details:not(.minimal-advanced)');if(json&&transport!=='xdrive'&&!extra.contains(json))extra.append(json);
}
const rtcTransportNames={datachannel:'DataChannel',vp8channel:'VP8Channel',seichannel:'SEIChannel',videochannel:'VideoChannel'};
function rtcTransports(provider){return {mtslink:['vp8channel'],salutejazz:['datachannel'],vkcalls:['vp8channel','seichannel','videochannel'],jitsi:['datachannel','vp8channel','seichannel','videochannel'],telemost:['vp8channel','datachannel','seichannel','videochannel']}[provider]||['datachannel'];}
function minimalCustomFields(id,s){
 const root=$('#protocol-fields');
 if(id==='raw'||s.id&&!s.provisioned){advancedProtocolFields(id,s);return;}
 const preset=(state.image_catalog||[]).find(i=>i.protocols.includes(id));
 let controls='';
 if(id==='olcrtc'){const provider=s.provider||'jitsi',transports=rtcTransports(provider),transport=transports.includes(s.rtc_transport)?s.rtc_transport:transports[0];controls=select('provider','Сервис звонков',[['jitsi','Jitsi'],['mtslink','МТС Линк'],['vkcalls','VK Звонки'],['salutejazz','Салют Jazz'],['telemost','Телемост']],provider)+field('room','Комната / ссылка звонка',s.room||'','required')+select('rtc_transport','Транспорт',transports.map(t=>[t,rtcTransportNames[t]]),transport);}
 if(id==='masterdns')controls=field('dns_domain','Домен DNS-туннеля',s.dns_domain||s.host||'','required')+'<p class="tip full">Ключ шифрования создастся автоматически. Клиент получит прямой адрес DNS-сервера со случайным портом. Делегация DNS нужна для подключения через сторонние рекурсивные резолверы.</p>';
 if(id==='openflux')controls=select('flux_transport','Площадка',[['cupsonline','cups.online · автоматически'],['yandex','Яндекс Документы'],['vyandex','Яндекс · видео'],['mailru','Mail.ru'],['telemost','Телемост']],s.flux_transport||'cupsonline')+field('room_url','Ссылка комнаты / документа',s.room_url||'','','url')+'<p class="tip full" id="flux-room-help"></p>';
 if(id==='warp')controls='<div class="tip full">Внешний доступ VLESS + Reality, выход через WARP. Ключи и приватный SOCKS-прокси настраиваются автоматически.</div>';
 if(id==='vkturn')controls='<div class="tip full">WireGuard-backend и ключи будут созданы автоматически. VK-ссылку укажите при выдаче подключения пользователю.</div>';
 if(id==='trusttunnel')controls=`<input type="hidden" name="security" value="tls"><input type="hidden" name="certificate_id" value="${esc(s.certificate_id||'')}"><input type="hidden" name="sni" value="${esc(s.sni||s.host||'')}"><div class="tip full">По умолчанию используется сертификат панели. При необходимости можно выпустить другой или загрузить PEM.</div><div class="grid full">${select('certificate_mode','Сертификат',[['domain','Домен · Let’s Encrypt'],['ip','IP · самоподписанный']],s.certificate_mode||'domain')}${field('certificate_host','Домен или IP для сертификата',s.certificate_host||s.host||'')}<div class="full"><button type="button" data-action="generate-cert">Выпустить сертификат</button><small id="certificate-status">${s.certificate_id?'Сертификат уже привязан':'Сертификат панели используется автоматически'}</small></div></div><details class="minimal-advanced full"><summary>Свой сертификат PEM</summary><div class="grid"><label>Сертификат<textarea name="certificate">${esc(s.certificate||'')}</textarea></label><label>Приватный ключ<textarea name="private_key">${esc(s.private_key||'')}</textarea></label></div></details>`;
 root.innerHTML=`<input type="hidden" name="simple_engine" value="true"><div class="grid">${controls}<div class="tip full">Конфигурация сервера и клиентские профили создаются панелью.${['olcrtc','masterdns','snolc','openflux'].includes(id)?' Одна персональная выдача на службу.':''}</div><details class="minimal-advanced full"><summary>Образ движка</summary><p class="mono">${esc(preset?.reference||'')}</p><p>Образ скачивается при запуске. Для локальных образов сначала выполните сборку в разделе «Образы».</p></details></div>`;
 if(id==='olcrtc')root.querySelector('[name="provider"]').onchange=()=>{
  Object.assign(s,Object.fromEntries(new FormData($('#service-form'))));
  const allowed=rtcTransports(s.provider);if(!allowed.includes(s.rtc_transport))s.rtc_transport=allowed[0];
  minimalCustomFields(id,s);
 };
 if(id==='openflux'){
  const transport=root.querySelector('[name="flux_transport"]'),room=root.querySelector('[name="room_url"]'),help=root.querySelector('#flux-room-help');
  const update=()=>{const automatic=transport.value==='cupsonline';room.required=!automatic;help.textContent=automatic?'Оставьте ссылку пустой: комнаты создадутся при сохранении, это может занять до двух минут. Сначала соберите образ OpenFlux в разделе «Образы».':'Укажите ссылку на существующую комнату или документ.';};
  transport.onchange=update;update();
 }

}

function configUpload(id,target){
 const wrap=document.createElement('div');wrap.className='full upload-box';
 const multi=['trusttunnel','snolc'].includes(id);
 const text=id==='trusttunnel'?'Загрузите vpn.toml, hosts.toml, credentials.toml и файлы сертификата':id==='snolc'?'Загрузите конфигурацию и совместимые модули snolc':id==='wireguard'||id==='amneziawg'?'Загрузите серверный файл .conf':id==='olcrtc'?'Загрузите YAML с комнатой и ключом olcRTC':id==='masterdns'?'Загрузите TOML сервера MasterDNS':'Загрузите готовую конфигурацию';
 wrap.innerHTML=`<label>${text}<input type="file" ${multi?'multiple':''} accept=".conf,.json,.toml,.yaml,.yml,.pem,.key,.crt,.so,.txt"><small class="upload-status">${target.value?'Конфигурация уже сохранена. Загрузите файл только для замены.':'Образ и команда выбраны автоматически. JSON вручную вводить не нужно.'}</small></label>`;
 wrap.querySelector('input').onchange=async e=>{
  const files=[...e.target.files];if(!files.length)return;
  try{
   if(files.reduce((n,f)=>n+f.size,0)>11000000)throw Error('Общий размер файлов — не более 11 МБ');
   if(!multi)target.value=await files[0].text();
   else{let values={};try{values=JSON.parse(target.value||'{}');}catch{}
    for(const f of files){if(f.name.endsWith('.so')){const bytes=new Uint8Array(await f.arrayBuffer());let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));values[f.name]={base64:btoa(str)};}else values[f.name]=await f.text();}
    target.value=JSON.stringify(values);
   }
   const portInput=target.form?.querySelector('[name="container_port"]');let detected;
   if(!multi){try{const cfg=JSON.parse(target.value);detected=cfg.inbounds?.[0]?.port||cfg.inbounds?.[0]?.listen_port;}catch{}const m=target.value.match(/^\s*(?:ListenPort|listen_port|port)\s*=\s*["']?(\d+)/im);detected=detected||m?.[1];}
   else{const cfg=JSON.parse(target.value);const match=(cfg['vpn.toml']||'').match(/(?:listen_address|listen_addr|address)\s*=\s*["'][^"']*:(\d+)/i);detected=match?.[1];}
   if(portInput&&detected&&Number(detected)>0&&Number(detected)<=65535)portInput.value=detected;
   wrap.querySelector('.upload-status').textContent='Загружено: '+files.map(f=>f.name).join(', ')+(detected?' · порт конфигурации '+detected:'');
  }catch(err){toast(err.message,true);}
 };
 return wrap;
}
document.addEventListener('change',e=>{if(e.target.name==='service_id'&&e.target.form?.id==='user-form')simplifyUser();if(e.target.name==='self_sni')simplifyNative('vless');});

let grantPersonId=null;
function turnFull(s){return s?.protocol==='wdtt'&&s.capacity?.free===0;}
function turnLimitText(s){return `В туннеле «${s?.name||'TURN'}» занято ${s?.capacity?.used??10} из ${s?.capacity?.limit??10} мест. Отключённые подписки тоже занимают место. Удалите ненужную подписку или создайте другой TURN-туннель.`;}
function serviceOptions(services,id,editing=false){return services.map(s=>`<option value="${s.id}" ${s.id===id?'selected':''} ${!editing&&turnFull(s)?'disabled':''}>${esc(s.name)} · ${esc(s.protocol)}${s.protocol==='wdtt'?` · ${s.capacity?.used??'?'} / ${s.capacity?.limit??10}${turnFull(s)?' — лимит достигнут':''}`:''}</option>`).join('');}
function personPicker(value=grantPersonId){return `<label>Владелец доступа<select name="person_id"><option value="">Новый пользователь</option>${(state.people||[]).map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`;}
function capacityInfo(services){return services.filter(turnFull).map(s=>`<div class="notice full">${esc(s.name)}: лимит подписок достигнут. <button type="button" data-action="turn-limit" data-id="${s.id}">Подробнее</button></div>`).join('');}
function trafficAccessCell(t){return t?.updated_at?`↑ ${size(t.current_upload)} / ↓ ${size(t.current_download)}<span class="subtext">Сегодня: ${size(t.today_total)} · Всё время: ${size(t.lifetime_total)}</span>`:'Ожидание статистики';}
function trafficCell(t){
 if(!t)return 'Ожидание статистики';
 const usage=t.updated_at?`${size(t.total)} · ↑ ${size(t.upload)} / ↓ ${size(t.download)}`:t.unsupported?.length?'Учёт недоступен':'Ожидание статистики';
 return `${usage}<span class="subtext">${t.limit?'Лимит '+size(t.limit):'Без лимита'}${t.pending?' · изменение доступа применяется':t.blocked?' · доступ заблокирован':''}${t.unsupported?.length?' · неполный учёт':''}${t.errors?.length?' · нет свежих данных':''}</span>${t.updated_at?`<span class="subtext">Сегодня: ${size(t.today_total||0)} · Всё время: ${size(t.lifetime_total??t.total)}</span>`:''}`;
}
function peoplePage(){
 const people=state.people||[];
 return heading('Пользователи','Подключения YPtun — в общей подписке, прокси Telegram — по отдельной ссылке.',false)+`<div class="section-heading"><span class="mono">${people.length} пользователей · ${state.users.length} подключений</span><button class="primary" data-action="person-new">＋ Создать пользователя</button></div><div class="panel">${people.length?`<div class="table-wrap"><table><thead><tr><th>ПОЛЬЗОВАТЕЛЬ</th><th>ПОДКЛЮЧЕНИЯ</th><th>ОБЩИЙ ТРАФИК / ЛИМИТ</th><th>ДЕЙСТВИЯ</th></tr></thead><tbody>${people.map(p=>{const links=state.users.filter(u=>u.person_id===p.id);return `<tr><td><strong>${esc(p.name)}</strong></td><td>${links.length} · ${links.filter(u=>u.enabled&&!u.quota_blocked&&(!u.expires_at||u.expires_at*1000>Date.now())).length} активных</td><td>${trafficCell(p.traffic)}</td><td><div class="actions"><button data-action="person-open" data-id="${p.id}">Подключения</button><button data-action="person-grant" data-id="${p.id}">＋ Выдать</button><button data-action="person-traffic" data-id="${p.id}">Трафик и лимит</button>${links.some(u=>state.services.find(s=>s.id===u.service_id)?.protocol!=='webproxy')?`<button data-action="person-sub" data-id="${p.id}">Подписка YPtun ↗</button>`:''}${links.filter(u=>state.services.find(s=>s.id===u.service_id)?.protocol==='webproxy').map(u=>`<button data-action="profile" data-id="${u.id}">Telegram ↗</button>`).join('')}<button data-action="person-edit" data-id="${p.id}">Имя</button>${!links.length?`<button data-action="person-delete" data-id="${p.id}">Удалить</button>`:''}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('Создайте пользователя','Выдавайте ему подключения к разным службам в любое время.','person-new','Создать пользователя')}</div>`;
}
async function peopleAction(action,id){
 const p=(state.people||[]).find(x=>x.id===id);
 if(action==='person-traffic'){
  const t=p.traffic||{},unsupported=t.unsupported?.length;
  openModal('Трафик · '+p.name,'Сумма отправленного и полученного трафика по всем подключениям пользователя.',`<p>${trafficCell(t)}</p><p class="mono">Текущий счётчик движков: ↑ ${size(t.current_upload||0)} / ↓ ${size(t.current_download||0)}. За сегодня: ↑ ${size(t.today_upload||0)} / ↓ ${size(t.today_download||0)}. День определяется по времени сервера.</p>${unsupported?`<div class="notice">Учёт недоступен для служб: ${t.unsupported.map(esc).join(', ')}. Для установки лимита удалите эти подключения.</div>`:''}${t.errors?.length?`<div class="notice">${t.errors.map(esc).join('; ')}.</div>`:''}<form id="traffic-form" data-id="${id}">${field('limit_gib','Лимит, ГиБ · 0 — без лимита',String((t.limit||0)/1024**3),'min="0" max="1000000" step="any" required','number')}<label><input type="checkbox" name="reset" value="true"> Сбросить расход для лимита (история «Сегодня» и «Всё время» сохранится)</label><p class="mono">Расход сохраняется до ручного сброса, включая удалённые подключения. При достижении лимита доступ блокируется. Проверка каждые 10 секунд; возможен небольшой перерасход. Сброс или увеличение лимита восстановит доступ, заблокированный лимитом.</p><p id="form-error" class="form-error"></p></form>`,`<button class="secondary" data-action="close">Отмена</button><button class="primary" type="submit" form="traffic-form">Сохранить</button>`);return;
 }
 if(action==='person-select-service'){userForm(id,grantPersonId);return;}
 if(action==='turn-limit'){const s=state.services.find(x=>x.id===id);openModal('Лимит TURN-подписок достигнут',turnLimitText(s),'<p>Выбор этого туннеля недоступен, пока не освободится место. Истёкшие доступы удаляет ядро автоматически.</p>',`<button class="primary" data-action="close">Понятно</button>`);return;}
 if(action==='edit-access'){const u=await api('users/'+id+'/settings'),s=state.services.find(x=>x.id===u.service_id);if(s.protocol==='wdtt'){await turnUserForm(s.id,u);return;}openModal('Изменить подключение',s.protocol==='webproxy'?'Новая ссылка появится в профиле подключения. В подписку прокси не входит.':'Изменения попадут в прежнюю подписку пользователя.',`<form id="access-edit-form" data-id="${id}"><div class="grid">${field('name','Метка подключения',u.name,'required maxlength="100"')}${['vless','vmess','warp'].includes(s.protocol)?field('uuid','Новый UUID (пусто — сохранить)','','autocomplete="off"'):''}${s.protocol==='webproxy'?field('webproxy_secret','Новый secret (пусто — сохранить)','','autocomplete="off" minlength="32" maxlength="32" pattern="[a-fA-F0-9]{32}"'):''}${['trojan','shadowsocks','hysteria2','trusttunnel'].includes(s.protocol)?field('password','Новый пароль (пусто — сохранить)','','autocomplete="new-password"','password'):''}${s.provisioned&&['wireguard','amneziawg','vkturn'].includes(s.protocol)?'<label class="full"><span><input type="checkbox" name="rotate_key" value="true"> Создать новый ключ подключения</span><small>Старый ключ перестанет работать. Новый появится в подписке.</small></label>':''}${s.protocol==='vkturn'&&s.provisioned?`<label class="full">VK-хеши / ссылки звонков<textarea name="vk_hash" required>${esc(u.vk_hash||'')}</textarea></label>`:''}${state.protocols.find(p=>p.id===s.protocol)?.mode==='custom'&&!s.provisioned?`<label class="full">Профиль<textarea name="profile">${esc(u.profile)}</textarea></label>`:''}<p id="form-error" class="form-error full"></p></div></form>`,`<button class="secondary" data-action="close">Отмена</button><button class="primary" type="submit" form="access-edit-form">Сохранить</button>`);return;}
 if(action==='person-new'||action==='person-edit'){openModal(p?'Изменить имя':'Новый пользователь','Подписка объединит подключения YPtun. Прокси Telegram выдаются отдельной ссылкой.',`<form id="person-form" data-id="${p?.id||''}">${field('name','Имя',p?.name||'','required maxlength="100"')}<p id="form-error" class="form-error"></p></form>`,`<button class="secondary" data-action="close">Отмена</button><button class="primary" type="submit" form="person-form">Сохранить</button>`);return;}
 if(action==='person-grant'){
  grantPersonId=id;
  const links=state.users.filter(u=>u.person_id===id);
  const existing=links.map(u=>{const s=state.services.find(s=>s.id===u.service_id);return `<label class="event"><span><input type="checkbox" name="keep" value="${esc(u.id)}" checked> ${esc(u.name)} <span class="subtext">${esc(s?.name||'Служба удалена')} · ${u.quota_blocked?'Лимит трафика':!u.enabled?'Отозван':u.expires_at&&u.expires_at*1000<Date.now()?'Истёк':'Активен'}</span></span></label>`;}).join('');
  const available=state.services.filter(s=>!links.some(u=>u.service_id===s.id)).map(s=>{
   const manual=(state.protocols.find(p=>p.id===s.protocol)?.mode==='custom'&&!s.provisioned)||s.protocol==='vkturn'||(s.protocol==='wdtt'&&!s.vk_hash);
   const full=turnFull(s);
   return `<div class="event"><label><input type="checkbox" name="add" value="${esc(s.id)}" ${manual||full?'disabled':''}> ${esc(s.name)}<span class="subtext">${esc(state.protocols.find(p=>p.id===s.protocol)?.name||s.protocol)}${s.protocol==='webproxy'?' · отдельная ссылка, без подписки':''}${full?' · лимит достигнут':manual?' · нужна ручная настройка':''}</span></label>${full?`<button type="button" data-action="turn-limit" data-id="${esc(s.id)}">Подробнее</button>`:manual?`<button type="button" data-action="person-select-service" data-id="${esc(s.id)}">Настроить</button>`:''}</div>`;
  }).join('');
  openModal('Подключения · '+p.name,'Отметьте нужные подключения. Снятие галочки удалит доступ и его ключ.',state.services.length||links.length?`<form id="person-connections-form" data-id="${esc(id)}"><div class="service-picker">${existing}${available}</div><p class="form-error" id="connections-error"></p></form>`:empty('Нет служб','Сначала создайте службу.','create'),`<button class="secondary" data-action="close">Отмена</button>${state.services.length||links.length?'<button class="primary" type="submit" form="person-connections-form">Сохранить</button>':''}`);return;
 }
 if(action==='person-delete'){await api('people/'+id+'/delete',{});modal.close();await load();return;}
 if(action==='person-rotate'){if(!$('#confirm-person-rotate')){openModal('Сменить адрес подписки','Старый адрес перестанет работать. Пользователю потребуется новый адрес.',`<span id="confirm-person-rotate"></span>`,`<button class="secondary" data-action="close">Отмена</button><button class="danger" data-action="person-rotate" data-id="${id}">Сменить адрес</button>`);return;}await api('people/'+id+'/rotate',{});await load();await peopleAction('person-sub',id);return;}
 if(action==='person-sub'){const url=location.origin+'/subscription/'+p.token;openModal('Подписка · '+p.name,'Импортируйте один раз в YPtun. Изменения появятся при обновлении подписки. Прокси Telegram выдаются отдельно.',shareSection('subscription-share','Постоянная ссылка')+'<p>Панель рекомендует обновление раз в час; также можно обновить подписку вручную в приложении.</p>',`<button class="secondary" data-action="person-rotate" data-id="${id}">Сменить адрес</button>`);bindShare('subscription-share',url,'yptun-subscription.txt');return;}
 if(action==='person-open'){const links=state.users.filter(u=>u.person_id===id);openModal('Подключения · '+p.name,'Можно выдать, изменить или отозвать любое подключение.',`<div class="panel">${links.length?links.map(u=>`<div class="event"><div><strong>${esc(u.name)}</strong><span class="subtext">${esc(state.services.find(s=>s.id===u.service_id)?.name)} · ${u.quota_blocked?'Лимит трафика':!u.enabled?'Отозван':u.expires_at&&u.expires_at*1000<Date.now()?'Истёк':'Активен'}</span><span class="subtext">${trafficAccessCell(u.traffic)}</span><div class="actions"><button data-action="profile" data-id="${u.id}">${state.services.find(s=>s.id===u.service_id)?.protocol==='webproxy'?'Telegram ↗':'Профиль'}</button><button data-action="edit-access" data-id="${u.id}">Изменить</button><button data-action="toggle" data-id="${u.id}">${u.enabled?'Отозвать':'Включить'}</button><button data-action="delete-user" data-id="${u.id}">Удалить</button></div></div></div>`).join(''):'<p>Подключений пока нет.</p>'}</div>`,`${links.some(u=>state.services.find(s=>s.id===u.service_id)?.protocol!=='webproxy')?`<button class="secondary" data-action="person-sub" data-id="${id}">Подписка YPtun</button>`:''}<button class="primary" data-action="person-grant" data-id="${id}">＋ Выдать подключение</button>`);}
}
function userForm(id,personId=null){
 grantPersonId=personId;
 if(!state.services.length){createForm();return;}
 const s=state.services.find(s=>s.id===id)||state.services.find(s=>!turnFull(s));
 if(!s){peopleAction('turn-limit',state.services[0].id);return;}
 if(turnFull(s)){peopleAction('turn-limit',s.id);return;}
 if(s.protocol==='wdtt'){turnUserForm(s.id);return;}
 const custom=state.protocols.find(p=>p.id===s.protocol)?.mode==='custom'&&!s.provisioned;
 openModal('Выдать подключение',s.protocol==='webproxy'?'Secret создаётся автоматически. Ссылка tg://webproxy будет в профиле; в подписку прокси не входит.':'Ключи создаются автоматически. Подключение добавится в подписку владельца.',`<form id="user-form"><div class="grid">${personPicker(personId)}${field('new_person_name','Имя нового пользователя','','maxlength="100"')}${field('name','Метка подключения','','required maxlength="100"')}<label>Служба<select name="service_id">${serviceOptions(state.services,s.id)}</select></label>${countryField(s.country||'')}${capacityInfo(state.services)}<details class="minimal-advanced full"><summary>Дополнительно</summary><div class="grid">${['vless','vmess','warp'].includes(s.protocol)?field('uuid','UUID (пусто — автоматически)','','autocomplete="off"'):''}${s.protocol==='webproxy'?field('webproxy_secret','Secret (пусто — автоматически)','','autocomplete="off" minlength="32" maxlength="32" pattern="[a-fA-F0-9]{32}"'):''}${['trojan','shadowsocks','hysteria2','trusttunnel'].includes(s.protocol)?field('password','Пароль (пусто — автоматически)','','autocomplete="new-password"','password'):''}</div></details>${custom?'<label class="full">Клиентский профиль импортированного движка<textarea name="profile" required rows="5"></textarea></label>':''}${s.protocol==='vkturn'?'<label class="full">VK-хеши / ссылки звонков<textarea name="vk_hash" required></textarea></label>':''}<p class="form-error full" id="form-error"></p></div></form>`,`<button class="secondary" data-action="close">Отмена</button><button class="primary" type="submit" form="user-form">Выдать доступ</button>`);
 setupNewAccess($('#user-form'),s);
}
function simplifyUser(){const form=$('#user-form');if(form)userForm(form.querySelector('[name="service_id"]').value,form.querySelector('[name="person_id"]').value||null);}
async function turnUserForm(id,u=null){
 const tunnels=state.services.filter(s=>s.protocol==='wdtt'),services=u?tunnels:state.services,selected=tunnels.find(s=>s.id===id);
 if(!tunnels.length){createForm('wdtt');return;}
 if(!u&&turnFull(selected)){await peopleAction('turn-limit',id);return;}
 openModal(u?'Изменить TURN-подключение':'Выдать TURN-подписку','Доступ войдёт в общую подписку пользователя.',`<form id="turn-user-form" data-id="${u?.id||''}"><div class="grid">${u?'':personPicker()+field('new_person_name','Имя нового пользователя','','maxlength="100"')}${field('name','Метка подключения',u?.name||'','required maxlength="64"')}<label>Туннель<select name="service_id" ${u?'disabled':''}>${serviceOptions(services,id,!!u)}</select></label>${u?'':countryField(selected.country||'')+capacityInfo(services)}${selected.vk_hash?'<div class="tip full">VK-ссылки берутся из настроек службы.</div>':`<label class="full">VK-хеши / ссылки на звонки (до 4)<textarea name="vk_hash" required>${esc(u?.vk_hash||'')}</textarea></label><div class="full" id="turn-hash-picker"></div>`}<details class="full minimal-advanced"><summary>Срок и устройства</summary><div class="grid">${field('days',u?'Продлить с текущего момента, дней':'Срок, дней',u?'':30,'min="1" max="365"','number')}${field('max_devices','Устройств',u?.max_devices||1,'min="1" max="10" required','number')}</div></details><p class="form-error full" id="form-error"></p></div></form>`,`<button class="secondary" data-action="close">Отмена</button><button class="primary" type="submit" form="turn-user-form">${u?'Сохранить':'Выдать доступ'}</button>`);
 if(!u)setupNewAccess($('#turn-user-form'),selected);
 if(selected.vk_hash)return;
 try{const r=await api('turn-hashes');if(!$('#turn-hash-picker'))return;$('#turn-hash-picker').innerHTML=`<label>Из библиотеки<select id="pick-vk-hash"><option value="">Выберите хеш</option>${r.hashes.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`;$('#pick-vk-hash').onchange=e=>{if(e.target.value)$('[name="vk_hash"]').value=e.target.value;};if(!u&&r.hashes.length===1){$('#pick-vk-hash').value=r.hashes[0];$('[name="vk_hash"]').value=r.hashes[0];}}catch(e){toast(e.message,true);}
}
document.addEventListener('change',e=>{if(e.target.name==='person_id')grantPersonId=e.target.value||null;});
document.addEventListener('submit',async e=>{
 const form=e.target;if(form.id!=='person-connections-form'||busy)return;
 e.preventDefault();
 const data=new FormData(form),add=data.getAll('add');
 const remove=[...form.querySelectorAll('input[name="keep"]:not(:checked)')].map(input=>input.value);
 if(remove.length&&!window.confirm(`Удалить подключений: ${remove.length}? Их ключи будут отозваны. Для импортированных конфигураций ключ необходимо удалить вручную.`))return;
 const button=document.querySelector('[form="person-connections-form"]');busy=true;button.disabled=true;
 let completed=0;
 try{
  for(const id of add){await api('people/'+form.dataset.id+'/grant',{service_id:id});completed++;}
  for(const id of remove){await api('users/'+id+'/delete',{});completed++;}
  modal.close();await load();toast('Подключения обновлены');
 }catch(err){
  await load();
  $('#connections-error').textContent=`Не удалось применить изменения: ${err.message}. Выполнено операций: ${completed}. Откройте список заново перед повтором.`;
  button.disabled=true;
 }finally{busy=false;if(!$('#connections-error')?.textContent)button.disabled=false;}
});

setInterval(()=>{if(page==='users'&&!modal.open&&!busy&&!$('#shell').hidden)load();},10000);
